def transform(grid):
    n = len(grid)
    # Uniform horizontal bands encode a repeating sequence of row colors.
    row_colors = []
    bands = True
    for row in grid:
        vals = set(row) - {0}
        if len(vals) > 1:
            bands = False
            break
        row_colors.append(next(iter(vals)) if vals else None)
    if bands:
        for period in range(1, n + 1):
            pattern = {}
            valid = True
            for i, color in enumerate(row_colors):
                if color is None:
                    continue
                residue = i % period
                if residue in pattern and pattern[residue] != color:
                    valid = False
                    break
                pattern[residue] = color
            if valid:
                fallback = next(iter(pattern.values()))
                colors = [pattern.get(i % period, fallback) for i in range(n)]
                return [[colors[i]] * len(grid[i]) for i in range(n)]

    # Otherwise, complete a cyclic diagonal pattern: each row is a shift
    # of one repeating color sequence.
    for direction in (-1, 1):
        pattern = {}
        valid = True
        for i, row in enumerate(grid):
            for j, color in enumerate(row):
                if color == 0:
                    continue
                k = (j + direction * i) % n
                if k in pattern and pattern[k] != color:
                    valid = False
                    break
                pattern[k] = color
            if not valid:
                break
        if valid and len(pattern) == n:
            return [[pattern[(j + direction * i) % n] for j in range(len(grid[i]))]
                    for i in range(n)]
    raise ValueError("No complete repeating pattern found")

